 void people(){heading(t("People","ആളുകൾ"),t("A separate ledger for each person. No interest.","ഓരോ ആൾക്കും സ്വന്തം കണക്കുപുസ്തകം. പലിശയില്ല."));LinearLayout actions=row();actions.addView(button(t("+ Lent","+ കൊടുത്ത കടം"),()->openEntry("lent"),true),new LinearLayout.LayoutParams(0,-2,1));actions.addView(button(t("+ Borrowed","+ വാങ്ങിയ കടം"),()->openEntry("borrowed"),false),new LinearLayout.LayoutParams(0,-2,1));body.addView(actions);gap(body,16);try(Cursor people=db.rawQuery("SELECT DISTINCT person FROM tx WHERE kind IN ('lent','borrowed') ORDER BY person COLLATE NOCASE",null)){if(people.getCount()==0)empty(t("No debts recorded","കടങ്ങൾ ചേർത്തിട്ടില്ല"),t("Add a person when recording money lent or borrowed. No phone contacts permission needed.","കടം ചേർക്കുമ്പോൾ പേര് നൽകുക. ഫോൺ കോൺടാക്ട് അനുമതി വേണ്ട."));while(people.moveToNext()){String person=people.getString(0);long receive=personOutstanding(person,"lent"),pay=personOutstanding(person,"borrowed"),net=Math.subtractExact(receive,pay);LinearLayout card=card();TextView title=text(person,20,FG,true);decorate(title,"person",person,36);card.addView(title);gap(card,8);card.addView(text(t("To receive ","കിട്ടാനുള്ളത് ")+ru(receive)+"   /   "+t("To repay ","കൊടുക്കാനുള്ളത് ")+ru(pay),13,MUTED,false));gap(card,6);card.addView(text(net==0?t("Net settled","ആകെ തീർന്നു"):(net>0?t("Net owed to you ","ആകെ നിങ്ങൾക്ക് കിട്ടാനുള്ളത് "):t("Net you owe ","ആകെ നിങ്ങൾ കൊടുക്കാനുള്ളത് "))+ru(Math.abs(net)),17,FG,true));card.setContentDescription(person+" "+t("ledger","കണക്കുകൾ"));card.setFocusable(true);card.setOnClickListener(v->{selectedPerson=person;page="person";render();});}}}
