 void aboutHisab(){if(accountUi!=null){accountUi.about();return;}dialog().setTitle("Hisab").setMessage(t("by AiCoN\n0.2.0-preview, private work in progress.\n\nManual entry. No ads, analytics, bank connection or working cloud sync. This preview has no internet permission and does not read notifications, SMS or contacts. Uninstalling removes local records. Saved backup and CSV files are separate.\n\nOriginal code, design and icons. Not financial advice.","by AiCoN\n0.2.0-preview, ടെസ്റ്റ് പതിപ്പ്.\n\nനിങ്ങൾ ചേർക്കുന്ന കണക്കുകൾ മാത്രം. പരസ്യമോ ട്രാക്കിങ്ങോ ബാങ്ക് ബന്ധമോ പ്രവർത്തിക്കുന്ന ക്ലൗഡ് സമന്വയമോ ഇല്ല. ഇന്റർനെറ്റ് അനുമതിയില്ല. നോട്ടിഫിക്കേഷൻ, SMS, കോൺടാക്ട് എന്നിവ വായിക്കില്ല. ആപ്പ് നീക്കിയാൽ ഫോണിലെ കണക്കുകൾ നഷ്ടപ്പെടും. ബാക്കപ്പും CSVയും വേറെയാണ്.\n\nസ്വന്തം കോഡും രൂപവും ഐക്കണുകളും. സാമ്പത്തിക ഉപദേശമല്ല.")).setPositiveButton(t("Done","കഴിഞ്ഞു"),null).setNeutralButton(t("Source code","സോഴ്സ് കോഡ്"),(di,n)->startActivity(new Intent(Intent.ACTION_VIEW,android.net.Uri.parse("https://github.com/aicon-hub/hisab")))).setNegativeButton("AiCoN",(di,n)->startActivity(new Intent(Intent.ACTION_VIEW,android.net.Uri.parse("https://aicon-hub.github.io/")))).show();}
