 @Override byte[] data()throws Exception{db.beginTransaction();try{JSONObject j=new JSONObject(new String(super.data(),java.nio.charset.StandardCharsets.UTF_8));j.put("schema",2);j.put("catalog",catalog.export());JSONObject preferences=settings.export();preferences.put("launcherIcon",prefs.getString("icon","Orange"));preferences.put("dailyReminders",ReminderSchedule.prefs(this).getBoolean("enabled",false)?"On":"Off");preferences.put("reminderMorning",String.valueOf(ReminderSchedule.time(this,0)));preferences.put("reminderEvening",String.valueOf(ReminderSchedule.time(this,1)));j.put("preferences",preferences);byte[] content=j.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8);db.setTransactionSuccessful();return content;}finally{db.endTransaction();}}
 @Override void validate(JSONObject j)throws Exception{
  backupKeys(j,"schema","tx","budgets","goals","catalog","preferences");long version=LedgerWire.integer(j,"schema");if(version!=1&&version!=2)throw new IllegalArgumentException("Unsupported backup version");
  Set<String> validAccounts=new HashSet<>(Arrays.asList("Cash","Bank","Wallet")),validCategories=new HashSet<>(Arrays.asList(builtInCategories));validCategories.add("Study");validCategories.add("Bills");
  if(j.has("preferences"))SettingsStore.validateExport(j.getJSONObject("preferences"));
  if(j.has("catalog")){JSONArray a=j.getJSONArray("catalog");CatalogStore.validateExport(a);validAccounts.clear();validCategories.clear();for(int i=0;i<a.length();i++){JSONObject o=a.getJSONObject(i);if(o.getString("type").equals("account"))validAccounts.add(o.getString("name"));if(o.getString("type").equals("category"))validCategories.add(o.getString("name"));}if(validAccounts.isEmpty()||validCategories.isEmpty())throw new IllegalArgumentException("Backup needs accounts and categories");}
  if(j.has("preferences")){Map<String,String> entityTypes=new HashMap<>();JSONArray entities=j.optJSONArray("catalog");if(entities!=null)for(int i=0;i<entities.length();i++){JSONObject item=entities.getJSONObject(i);entityTypes.put(item.getString("uuid"),item.getString("type"));}SettingsStore.validateReferences(j.getJSONObject("preferences"),entityTypes);}
  JSONArray tx=j.getJSONArray("tx"),budgets=j.getJSONArray("budgets"),goals=j.getJSONArray("goals");if(tx.length()>20000||budgets.length()>100||goals.length()>1000)throw new IllegalArgumentException("Backup is too large");
  Set<Long> rowIds=new HashSet<>();Set<String> uuids=new HashSet<>(),budgetNames=new HashSet<>();uuids.add(LedgerWire.PREFERENCES_ID);if(j.has("catalog")){JSONArray entities=j.getJSONArray("catalog");for(int n=0;n<entities.length();n++)uuids.add(entities.getJSONObject(n).getString("uuid"));}List<LedgerIntegrity.Entry> whole=new ArrayList<>();
  for(int i=0;i<tx.length();i++){JSONObject o=tx.getJSONObject(i);backupKeys(o,"id","kind","amount","day","account","dest","category","note","uuid","person","loan");long id=LedgerWire.integer(o,"id"),amount=LedgerWire.amount(o,"amount",false);if(id<=0||!rowIds.add(id))throw new IllegalArgumentException("Invalid row identity");String kind=LedgerWire.text(o,"kind",20,true),day=LedgerWire.text(o,"day",10,true),account=LedgerWire.text(o,"account",80,true),dest=LedgerWire.text(o,"dest",80,false),category=LedgerWire.text(o,"category",80,true);validDate(day);LedgerWire.text(o,"note",160,false);
   if(!validAccounts.contains(account)||!Arrays.asList(version==1?new String[]{"expense","income","transfer"}:new String[]{"expense","income","transfer","lent","borrowed","repay_in","repay_out"}).contains(kind))throw new IllegalArgumentException("Invalid entry account or type");if(kind.equals("transfer")){if(!validAccounts.contains(dest)||account.equals(dest)||!category.equals("Transfer"))throw new IllegalArgumentException("Invalid transfer");}else if(!dest.isEmpty())throw new IllegalArgumentException("Unexpected destination");
   boolean debt=kind.equals("lent")||kind.equals("borrowed")||kind.startsWith("repay_");if(debt?!category.equals("Debt"):!kind.equals("transfer")&&!validCategories.contains(category))throw new IllegalArgumentException("Invalid category");
   if(version==2){String uuid=backupUuid(o,uuids,true);whole.add(new LedgerIntegrity.Entry(uuid,kind,amount,day,account,dest,LedgerWire.text(o,"person",80,false),LedgerWire.text(o,"loan",36,false)));}
  }
  if(version==2)LedgerIntegrity.validate(whole,validAccounts);
  for(int i=0;i<budgets.length();i++){JSONObject o=budgets.getJSONObject(i);backupKeys(o,"category","amount","uuid");String category=LedgerWire.text(o,"category",80,true);if(!validCategories.contains(category)||!budgetNames.add(category))throw new IllegalArgumentException("Invalid budget category");LedgerWire.amount(o,"amount",false);backupUuid(o,uuids,false);}
  rowIds.clear();for(int i=0;i<goals.length();i++){JSONObject o=goals.getJSONObject(i);backupKeys(o,"id","name","target","saved","uuid");long id=LedgerWire.integer(o,"id");if(id<=0||!rowIds.add(id))throw new IllegalArgumentException("Invalid goal identity");LedgerWire.text(o,"name",80,true);LedgerWire.amount(o,"target",false);LedgerWire.amount(o,"saved",true);backupUuid(o,uuids,false);}
 }
 static void backupKeys(JSONObject o,String... allowed){Set<String> keys=new HashSet<>(Arrays.asList(allowed));Iterator<String> it=o.keys();while(it.hasNext())if(!keys.contains(it.next()))throw new IllegalArgumentException("Unexpected backup field");}
 static String backupUuid(JSONObject o,Set<String> used,boolean required)throws Exception{if(!required&&(!o.has("uuid")||o.optString("uuid").isEmpty()))return "";String uuid=LedgerWire.text(o,"uuid",36,true);Identifiers.uuid(uuid);if(!used.add(uuid))throw new IllegalArgumentException("Duplicate record UUID");return uuid;}
 @Override void restore(JSONObject j)throws Exception{if(session.accountLedger())throw new IllegalStateException("Restore backups in the separate local-only ledger. No cloud ledger replaced.");final LedgerSession.Ticket ticket=session.ticket();validate(j);j=new JSONObject(j.toString());for(String table:new String[]{"budgets","goals"}){JSONArray a=j.getJSONArray(table);for(int n=0;n<a.length();n++){JSONObject o=a.getJSONObject(n);if(!o.has("uuid")||o.optString("uuid").isEmpty())o.put("uuid",UUID.randomUUID().toString());}}if(j.getInt("schema")==1){JSONArray tx=j.getJSONArray("tx");for(int i=0;i<tx.length();i++){JSONObject o=tx.getJSONObject(i);o.put("uuid",UUID.randomUUID().toString());o.put("person","");o.put("loan","");}}final JSONObject restored=j;session.edit(ticket,(ledger,entities,preferences)->{super.restore(restored);if(restored.has("catalog"))catalog.restore(restored.getJSONArray("catalog"));else{db.delete("catalog",null,null);db.delete("catalog_meta",null,null);catalog.seed(builtInCategories,new String[]{"Cash","Bank","Wallet"});}settings.restore(restored.optJSONObject("preferences")==null?new JSONObject():restored.getJSONObject("preferences"));});refreshCatalog();ml=settings.get("language").equals("ml");dark=settings.get("surface").equals("Liquid Glass")||settings.get("appearance").equals("Dark");prefs.edit().putBoolean("ml",ml).putBoolean("dark",dark).apply();ReminderSchedule.prefs(this).edit().putInt("time0",Integer.parseInt(settings.get("reminderMorning"))).putInt("time1",Integer.parseInt(settings.get("reminderEvening"))).apply();ReminderSchedule.prefs(this).edit().putBoolean("enabled",settings.get("dailyReminders").equals("On")&&ReminderSchedule.allowed(this)).apply();ReminderSchedule.schedule(this);try{AppIcon.choose(this,settings.get("launcherIcon"));}catch(Exception iconError){toast("Ledger restored. Launcher icon could not update; choose it again in settings.");}quickKind=settings.get("defaultKind");}
 @Override void exportCSV(){final Object owner=actionTicket();dialog().setTitle(t("Export unencrypted CSV?","എൻക്രിപ്റ്റ് ചെയ്യാത്ത CSV വേണോ? ")).setMessage(t("Includes people's names and debts. Anyone with the file can read it.","പേരുകളും കടങ്ങളും ഉൾപ്പെടും. ഫയൽ കിട്ടുന്നവർക്ക് വായിക്കാം.")).setNegativeButton(t("Cancel","വേണ്ട"),null).setPositiveButton(t("Export","എക്സ്പോർട്ട്"),(di,n)->{if(!actionCurrent(owner)){toast("Ledger changed. Reopen export.");return;}StringBuilder out=new StringBuilder("Date,Type,Amount_"+settings.get("currency")+",Account,Destination,Category,Note,Person,Record_UUID,Loan_UUID\r\n");Cursor c=db.rawQuery("SELECT * FROM tx ORDER BY day,id",null);while(c.moveToNext()){String[] row={c.getString(3),c.getString(1),Ledger.number(c.getLong(2)),c.getString(4),c.getString(5),c.getString(6),c.getString(7),c.getString(c.getColumnIndexOrThrow("person")),c.getString(c.getColumnIndexOrThrow("uuid")),c.getString(c.getColumnIndexOrThrow("loan"))};for(int i=0;i<row.length;i++){if(i>0)out.append(',');String value=row[i];if(value.matches("^[=+@\\-].*"))value="'"+value;out.append(Ledger.csv(value));}out.append("\r\n");}c.close();saveFile(out.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8),"text/csv","Hisab-entries.csv");}).show();}

 static int mix(int a,int b,float weight){return android.graphics.Color.rgb(Math.round(android.graphics.Color.red(a)*(1-weight)+android.graphics.Color.red(b)*weight),Math.round(android.graphics.Color.green(a)*(1-weight)+android.graphics.Color.green(b)*weight),Math.round(android.graphics.Color.blue(a)*(1-weight)+android.graphics.Color.blue(b)*weight));}
