 void balanceInfo(){dialog().setTitle(t("Balance and cash flow","ബാലൻസും വരുമാനവും")).setMessage(t("Available across accounts is the current balance of every account, including loans and repayments. The income and spending figures apply to the selected month only. Transfers, loans and repayments do not count as income or expenses. This is a manual ledger, not a bank feed.","എല്ലാ അക്കൗണ്ടുകളുടെയും ഇപ്പോഴത്തെ ബാലൻസാണ് മുകളിൽ. വരുമാനവും ചെലവും തിരഞ്ഞെടുത്ത മാസത്തേതാണ്. കൈമാറ്റം, കടം, തിരിച്ചടവ് എന്നിവ വരുമാനമോ ചെലവോ അല്ല. ബാങ്കിൽ നിന്ന് തനിയെ വിവരങ്ങൾ വരുന്നില്ല.")).setPositiveButton(t("Done","കഴിഞ്ഞു"),null).show();}
 ImageView profileImage(int size){ImageView photo=new ImageView(this){@Override protected void onDraw(android.graphics.Canvas c){int save=c.save();android.graphics.Path path=new android.graphics.Path();path.addCircle(getWidth()/2f,getHeight()/2f,Math.min(getWidth(),getHeight())/2f,android.graphics.Path.Direction.CW);c.clipPath(path);super.onDraw(c);c.restoreToCount(save);}};android.graphics.Bitmap bitmap=ProfilePhotos.load(this,profileKey());if(bitmap!=null){photo.setImageBitmap(bitmap);photo.setScaleType(ImageView.ScaleType.CENTER_CROP);}else{photo.setImageDrawable(new CategoryMark(16,ORANGE));photo.setPadding(d(9),d(9),d(9),d(9));}photo.setBackground(glass(size));photo.setContentDescription(t("Profile photo","പ്രൊഫൈൽ ഫോട്ടോ"));photo.setOnClickListener(v->profileDetailsMenu());return photo;}
 void profileDetailsMenu(){dialog().setTitle(t("Your profile","പ്രൊഫൈൽ")).setItems(new String[]{t("Edit profile details","വിവരങ്ങൾ തിരുത്തുക"),t("Choose profile photo","ഫോട്ടോ തിരഞ്ഞെടുക്കുക"),t("Remove profile photo","ഫോട്ടോ നീക്കുക")},(di,n)->{if(n==0)editProfileDetails();else if(n==1)pickProfilePhoto();else try{ProfilePhotos.remove(this,profileKey());render();}catch(Exception e){toast("Could not remove photo.");}}).setNegativeButton(t("Done","കഴിഞ്ഞു"),null).show();}
 int chartWeekOffset;
 void weeklyChart(){java.time.LocalDate date=java.time.LocalDate.now();java.time.YearMonth month=java.time.YearMonth.parse(viewedMonth());java.time.LocalDate end=month.equals(java.time.YearMonth.from(date))?date:month.atEndOfMonth();end=end.minusDays(chartWeekOffset*7L);java.time.LocalDate start=end.minusDays(6);final java.time.LocalDate first=start,last=end;long[] values=new long[7];try(Cursor c=db.rawQuery("SELECT day,coalesce(sum(amount),0) FROM tx WHERE kind='expense' AND day>=? AND day<=? GROUP BY day",new String[]{start.toString(),end.toString()})){while(c.moveToNext()){int index=(int)java.time.temporal.ChronoUnit.DAYS.between(start,java.time.LocalDate.parse(c.getString(0)));if(index>=0&&index<7)values[index]=c.getLong(1);}}
 sectionTitle(t("Spending this week","ആഴ്ചയിലെ ചെലവ്"),t("Reports ↗","റിപ്പോർട്ട് ↗"),()->{page="reports";render();});LinearLayout panel=card();long total=0;for(long value:values)total=Math.addExact(total,value);panel.addView(text(ru(total)+t(" spent"," ചെലവ്"),19,FG,true));gap(panel,5);panel.addView(text(displayDate(start.toString())+" – "+displayDate(end.toString()),11,MUTED,false));WeekChart graph=new WeekChart(this,values,start,FG,MUTED,ORANGE,HERO);graph.setContentDescription(t("Weekly daily expenses: ","ദിവസത്തെ ചെലവുകൾ: ")+ru(total));graph.setFocusable(true);graph.onDay=i->dialog().setTitle(displayDate(first.plusDays(i).toString())).setMessage(t("Expenses ","ചെലവ് ")+ru(values[i])+"\n"+t("Transfers, loans and repayments excluded.","കൈമാറ്റവും കടവും തിരിച്ചടവും ഉൾപ്പെടുത്തിയിട്ടില്ല.")).setPositiveButton(t("Done","കഴിഞ്ഞു"),null).show();panel.addView(graph,new LinearLayout.LayoutParams(-1,d(132)));LinearLayout control=row();control.addView(button("‹",()->{chartWeekOffset++;render();},false),new LinearLayout.LayoutParams(d(48),d(44)));TextView detail=button(t("Daily values","ഓരോ ദിവസത്തെ തുക"),()->{StringBuilder text=new StringBuilder();for(int i=0;i<7;i++)text.append(displayDate(first.plusDays(i).toString())).append("  ").append(ru(values[i])).append("\n");dialog().setTitle(t("Daily expenses","ദിവസത്തെ ചെലവ്")).setMessage(text.toString()).setPositiveButton(t("Done","കഴിഞ്ഞു"),null).show();},false);control.addView(detail,new LinearLayout.LayoutParams(0,d(44),1));TextView next=button("›",()->{chartWeekOffset=Math.max(0,chartWeekOffset-1);render();},false);next.setEnabled(chartWeekOffset>0);control.addView(next,new LinearLayout.LayoutParams(d(48),d(44)));panel.addView(control);}

