 void annualReport(){int year=java.time.YearMonth.parse(viewedMonth()).getYear();long[] expenses=new long[12],incomes=new long[12];try(Cursor c=db.rawQuery("SELECT substr(day,6,2),kind,sum(amount) FROM tx WHERE substr(day,1,4)=? AND day<=? AND kind IN ('expense','income') GROUP BY 1,2",new String[]{String.valueOf(year),today()})){while(c.moveToNext()){int index=Integer.parseInt(c.getString(0))-1;if(index>=0&&index<12){if(c.getString(1).equals("expense"))expenses[index]=c.getLong(2);else incomes[index]=c.getLong(2);}}}LinearLayout panel=card();panel.addView(text(year+t(" · cumulative spending"," · ആകെ ചെലവ്"),18,FG,true));gap(panel,5);panel.addView(text(t("Through today. Tap monthly values below for exact totals.","ഇന്നുവരെയുള്ള കണക്കുകൾ. ഓരോ മാസത്തെയും തുക താഴെ."),11,MUTED,false));int through=year<java.time.LocalDate.now().getYear()?12:year==java.time.LocalDate.now().getYear()?java.time.LocalDate.now().getMonthValue():0;LedgerChart line=new LedgerChart(this,expenses,new int[]{ORANGE},false,through,FG,MUTED,ORANGE);line.labels(t("No expenses through today","ഇന്നുവരെ ചെലവില്ല"),t("Expenses","ചെലവുകൾ"));line.axisLabels("Jan","Dec");panel.addView(line,new LinearLayout.LayoutParams(-1,d(160)));for(int i=0;i<12;i++){final int index=i;String month=java.time.Month.of(i+1).getDisplayName(java.time.format.TextStyle.SHORT,ml?new Locale("ml","IN"):Locale.ENGLISH);settingRow(panel,month,t("Spent ","ചെലവ് ")+ru(expenses[i])+" / "+t("Income ","വരുമാനം ")+ru(incomes[i]),27,()->{reportingMonth=java.time.YearMonth.of(year,index+1).toString();reportPeriod="Month";render();});}panel.addView(text(t("Loans, transfers and repayments excluded. Future entries are not shown in this through-today view.","കടം, കൈമാറ്റം, തിരിച്ചടവ്, ഭാവിയിലെ കണക്കുകൾ എന്നിവ ഈ കാഴ്ചയിൽ ഇല്ല."),11,MUTED,false));}
